/**
 * Loads schema-data.json for structured query/type lookups.
 */
import { readFileSync, existsSync } from 'fs';
/**
 * Load schema data from the pre-built JSON file.
 * @param schemaPath - Direct path to `schema-data.json`
 */
export function loadSchemaData(schemaPath) {
    if (!existsSync(schemaPath)) {
        console.warn(`[schema-loader] Schema data not found: ${schemaPath}`);
        console.warn('[schema-loader] Data files may be missing — try reinstalling the package.');
        return null;
    }
    let data;
    try {
        const raw = readFileSync(schemaPath, 'utf-8');
        data = JSON.parse(raw);
    }
    catch (err) {
        console.warn(`[schema-loader] Failed to parse schema data: ${err.message}`);
        return null;
    }
    if (!data ||
        !Array.isArray(data.rootQueries) ||
        !Array.isArray(data.objectTypes) ||
        !Array.isArray(data.enums) ||
        !Array.isArray(data.inputTypes) ||
        !Array.isArray(data.scalars) ||
        !Array.isArray(data.interfaces)) {
        console.warn('[schema-loader] Schema data has invalid shape');
        return null;
    }
    const total = data.rootQueries.length + data.objectTypes.length + data.enums.length
        + data.inputTypes.length + data.scalars.length + data.interfaces.length;
    console.error(`[schema-loader] Loaded schema: ${total} definitions`);
    return data;
}
